mapper.update:
UPDATE gw_notice
   SET deleted_at = CURRENT_TIMESTAMP, updated_by = #{userId}
 WHERE notice_id = #{noticeId}

mapper.select:
SELECT FROM gw_notice n LEFT JOIN gw_user u ON u.user_id = n.author_id WHERE n.deleted_at IS NULL
AND (LOWER(n.title) LIKE LOWER('%' || #{keyword} || '%') OR LOWER(n.content) LIKE LOWER('%' || #{keyword} || '%'))
ORDER BY n.pinned_yn DESC, n.created_at DESC LIMIT #{limit} OFFSET #{offset}

mapper.delete:
DELETE FROM gw_notice_comment
 WHERE cmt_id = #{cmtId}
   AND (author_id = #{authorId} OR #{roleCd} IN ('ADMIN','HR_MANAGER'))
